settings.liquid:
{% assign review = "Scentech's nebulizing technology offers pure, consistent fragrance, and the app makes customizing scent intensity and schedules effortless. A truly luxurious home experience." %}
{% assign author = "- Dr. Amy Johnson, Fragrance Chemist" %}
{% assign image = "https://cdn.shopify.com/s/files/1/0888/1219/2090/files/Fragrance_Chemist.png?v=1729861874" %}
{% assign rating = 5 %}

<div class="featured-review">
    <img class="review-img" src="{{ image }}" alt="Review">

    <div class="content">
        <div class="stars">
            {% for i in (1..rating) %}
            <span class="star"></span>
            {% endfor %}
        </div>

        <div class="review-text">"{{ review }}"</div>

        <div class="author-info">
            {{ author }}
        </div>
    </div>
</div>

<style>
    .featured-review {
        display: flex;
        align-items: center;
        gap: 20px;
    }

    .review-img {
        width: 75px;
        height: 75px;
        border-radius: 50%;
    }

    .content {
        display: flex;
        flex-direction: column;
        gap: 8px;
    }

    .stars {
        display: flex;
        gap: 2px;
    }

    .star {
        width: 13px;
        height: 13px;
        background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="%23FFD700" d="M12 .587l3.668 7.429 8.332 1.19-6.004 5.897 1.416 8.267L12 18.896l-7.412 3.374 1.416-8.267-6.004-5.897 8.332-1.19z"/></svg>') no-repeat center;
        background-size: cover;
    }

    .review-text {
        font-size: 0.8rem;
        line-height: 18px;
        text-align: left;
        font-family: 'DIN Next Regular', sans-serif; /* Use DIN Next Regular */
    }

    .author-info {
        font-size: 0.8rem;
        font-weight: Bold;
        font-family: 'DIN Next Regular', sans-serif; /* Use DIN Next Regular */
    }

    @media (max-width: 290px) {
        .featured-review {
            flex-direction: column;
        }

        .content .stars, .content .author-info {
            justify-content: center;
        }

        .content .review-text {
            text-align: center;
        }
    }
</style>
